static const uint8_t *cn16_lookup(uint32_t cp)
{
    for (size_t i = 0U; i < sizeof(cn16_glyphs) / sizeof(cn16_glyphs[0]); ++i) {
        if (cn16_glyphs[i].unicode == cp) return cn16_glyphs[i].bits;
    }
    return NULL;
}

uint32_t LCD_CN16_GlyphCount(void)
{
    return (uint32_t)(sizeof(cn16_glyphs) / sizeof(cn16_glyphs[0]));
}

LCD_Result LCD_CN16_DrawGlyph(LCD_Device *dev, uint16_t x, uint16_t y,
                             uint32_t codepoint, uint16_t foreground, uint16_t background)
{
    if (dev == NULL) return LCD_ERROR_PARAM;
    if ((uint32_t)x + 16U > dev->width || (uint32_t)y + 16U > dev->height)
        return LCD_ERROR_PARAM;
    const uint8_t *bits = cn16_lookup(codepoint);
    if (bits == NULL) return LCD_ERROR_PARAM;
    /* LCD_ShowPicture requires 16*16*2 big-endian RGB565 bytes.
     * This buffer is single-owner LCD Task only, no shared concurrent callers. */
    static uint8_t pixels[16U * 16U * 2U];
    for (uint32_t row = 0U; row < 16U; ++row) {
        for (uint32_t col = 0U; col < 16U; ++col) {
            const uint8_t bit = (uint8_t)(1U << (col & 7U));
            const uint16_t color = (bits[row * 2U + (col >> 3U)] & bit)
                                  ? foreground : background;
            const uint32_t offset = (row * 16U + col) * 2U;
            pixels[offset] = (uint8_t)(color >> 8U);
            pixels[offset + 1U] = (uint8_t)color;
        }
    }
    return LCD_ShowPicture(dev, x, y, 16U, 16U, pixels);
}

LCD_Result LCD_CN16_ShowText(LCD_Device *dev, uint16_t x, uint16_t y,
                            const char *utf8, uint16_t foreground, uint16_t background)
{
    if (dev == NULL || utf8 == NULL || (uint32_t)y + 16U > dev->height)
        return LCD_ERROR_PARAM;
    const uint8_t *p = (const uint8_t *)utf8;
    while (*p != 0U) {
        if (*p < 0x80U) {
            if ((uint32_t)x + 8U > dev->width) return LCD_ERROR_PARAM;
            const uint8_t ch = (*p >= 32U && *p <= 126U) ? *p : (uint8_t)'?';
            const LCD_Result s = LCD_ShowChar(dev, x, y, ch, &ASCII_Font16, foreground, background);
            if (s != LCD_OK) return s;
            x = (uint16_t)(x + 8U);
            ++p;
            continue;
        }
        uint32_t cp = 0U;
        uint32_t used = 1U;
        /* UI font targets only valid 3-byte UTF-8 CJK characters. */
        if (p[0] >= 0xE0U && p[0] <= 0xEFU && p[1] != 0U && p[2] != 0U &&
            (p[1] & 0xC0U) == 0x80U && (p[2] & 0xC0U) == 0x80U) {
            cp = ((uint32_t)(p[0] & 0x0FU) << 12U) |
                 ((uint32_t)(p[1] & 0x3FU) << 6U) | (uint32_t)(p[2] & 0x3FU);
            used = 3U;
        }
        if (cn16_lookup(cp) != NULL) {
            if ((uint32_t)x + 16U > dev->width) return LCD_ERROR_PARAM;
            const LCD_Result s = LCD_CN16_DrawGlyph(dev, x, y, cp, foreground, background);
            if (s != LCD_OK) return s;
            x = (uint16_t)(x + 16U);
        } else {
            /* Unknown glyph uses a single ASCII question mark, no accidental raw UTF-8. */
            if ((uint32_t)x + 8U > dev->width) return LCD_ERROR_PARAM;
            const LCD_Result s = LCD_ShowChar(dev, x, y, (uint8_t)'?', &ASCII_Font16, foreground, background);
            if (s != LCD_OK) return s;
            x = (uint16_t)(x + 8U);
        }
        p += used;
    }
    return LCD_OK;
}
